#!/bin/bash
cd /home/ibex || exit 1
set +e

TEST_NAME=csr_trap_csrs
TB_ROOT=/home/ibex/.tb/${TEST_NAME}
BUILD_DIR=/home/ibex/.tb/${TEST_NAME}_build

mkdir -p "$TB_ROOT"
rm -rf "$BUILD_DIR"

cat >"$TB_ROOT/csr_tb.cpp" <<'EOF'
#include "Vibex_cs_registers.h"
#include "verilated.h"

#include <cstdint>
#include <iostream>

static vluint64_t main_time = 0;

double sc_time_stamp() { return static_cast<double>(main_time); }

static void tick(Vibex_cs_registers &top) {
  top.clk_i = 0;
  top.eval();
  ++main_time;
  top.clk_i = 1;
  top.eval();
  ++main_time;
}

static void drive_defaults(Vibex_cs_registers &top) {
  top.core_id_i = 0;
  top.cluster_id_i = 0;
  top.csr_access_i = 0;
  top.csr_addr_i = 0;
  top.csr_wdata_i = 0;
  top.csr_op_i = 0;
  top.debug_cause_i = 0;
  top.debug_csr_save_i = 0;
  top.pc_if_i = 0;
  top.pc_id_i = 0;
  top.csr_save_if_i = 0;
  top.csr_save_id_i = 0;
  top.csr_restore_mret_i = 0;
  top.csr_restore_dret_i = 0;
  top.csr_save_cause_i = 0;
  top.csr_mtvec_i = 0x12345001u;
  top.csr_mcause_i = 0;
  top.csr_mtval_i = 0;
  top.insn_ret_i = 0;
  top.id_valid_i = 1;
  top.instr_is_compressed_i = 0;
  top.is_decoding_i = 1;
  top.imiss_i = 0;
  top.pc_set_i = 0;
  top.jump_i = 0;
  top.branch_i = 0;
  top.branch_taken_i = 0;
  top.mem_load_i = 0;
  top.mem_store_i = 0;
  top.lsu_busy_i = 0;
}

static void csr_write(Vibex_cs_registers &top, uint16_t addr, uint32_t data) {
  top.csr_access_i = 1;
  top.csr_addr_i = addr;
  top.csr_wdata_i = data;
  top.csr_op_i = 1;
  top.eval();
  tick(top);
  top.csr_access_i = 0;
  top.csr_op_i = 0;
  top.csr_wdata_i = 0;
  top.eval();
}

static uint32_t csr_read(Vibex_cs_registers &top, uint16_t addr) {
  top.csr_access_i = 1;
  top.csr_addr_i = addr;
  top.csr_op_i = 0;
  top.eval();
  uint32_t value = top.csr_rdata_o;
  top.csr_access_i = 0;
  top.eval();
  return value;
}

int main(int argc, char **argv) {
  Verilated::commandArgs(argc, argv);
  Vibex_cs_registers top;

  drive_defaults(top);
  top.rst_ni = 0;
  tick(top);
  tick(top);
  top.rst_ni = 1;
  top.eval();

  if (csr_read(top, 0x305) != 0x12345001u) {
    std::cerr << "mtvec readback mismatch" << std::endl;
    top.final();
    return 1;
  }

  csr_write(top, 0x340, 0x11223344u);
  if (csr_read(top, 0x340) != 0x11223344u) {
    std::cerr << "mscratch readback mismatch" << std::endl;
    top.final();
    return 2;
  }

  top.pc_id_i = 0x200u;
  top.csr_mcause_i = 0x0bu;
  top.csr_mtval_i = 0xdeadbeefu;
  top.csr_save_cause_i = 1;
  top.eval();
  tick(top);
  top.csr_save_cause_i = 0;
  top.eval();

  if (top.csr_mepc_o != 0x200u) {
    std::cerr << "mepc save mismatch" << std::endl;
    top.final();
    return 3;
  }
  if (csr_read(top, 0x342) != 0x0000000bu) {
    std::cerr << "mcause mismatch" << std::endl;
    top.final();
    return 4;
  }
  if (csr_read(top, 0x343) != 0xdeadbeefu) {
    std::cerr << "mtval mismatch" << std::endl;
    top.final();
    return 5;
  }

  std::cout << "CSR trap test PASS" << std::endl;
  top.final();
  return 0;
}
EOF

verilator -Wall -Wno-fatal --cc --exe --build \
  --top-module ibex_cs_registers \
  -sv rtl/ibex_defines.sv rtl/ibex_cs_registers.sv "$TB_ROOT/csr_tb.cpp" \
  --Mdir "$BUILD_DIR" 2>&1 | tee "$TB_ROOT/build.log"
rc=${PIPESTATUS[0]}

echo "HWE_BENCH_RESULTS_START"

if [ "$rc" -ne 0 ]; then
  echo "TEST: $TEST_NAME ... FAIL"
  echo "HWE_BENCH_RESULTS_END"
  exit 1
fi

"$BUILD_DIR/Vibex_cs_registers" 2>&1 | tee "$TB_ROOT/run.log"
rc=${PIPESTATUS[0]}

if [ "$rc" -eq 0 ]; then
  echo "TEST: $TEST_NAME ... PASS"
  echo "HWE_BENCH_RESULTS_END"
  exit 0
fi

echo "TEST: $TEST_NAME ... FAIL"
echo "HWE_BENCH_RESULTS_END"
exit 1

