#!/bin/bash
cd /home/ibex
set -uo pipefail

TEST_NAME="rvfi_retire_alignment"
TB_DIR="/home/ibex/.tb_${TEST_NAME}"

report_and_exit() {
  local status="$1"
  local rc="$2"

  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: ${TEST_NAME} ... ${status}"
  echo "HWE_BENCH_RESULTS_END"
  exit "$rc"
}

