  >"$BUILD_LOG" 2>&1
build_rc=$?
if [ "$build_rc" -ne 0 ]; then
  emit_test_result "build" "FAIL"
  tail -n 40 "$BUILD_LOG"
  exit "$build_rc"
fi

timeout 60 "$SIM_BIN" >"$SIM_LOG" 2>&1
sim_rc=$?
set -e

cat "$SIM_LOG"

if [ "$sim_rc" -ne 0 ] && [ "$sim_rc" -ne 124 ]; then
