tb_script:
#!/bin/bash
set -euo pipefail

cd /home/ibex

TEST_NAME="prefetch_rvalid_path"
TB_DIR="/home/ibex/.tb_${TEST_NAME}"
OBJ_DIR="${TB_DIR}/obj_dir"
TB_CPP="${TB_DIR}/${TEST_NAME}_tb.cpp"
SIM_BIN="${OBJ_DIR}/Vibex_prefetch_buffer"

mkdir -p "${TB_DIR}"
rm -rf "${OBJ_DIR}"

cat > "${TB_CPP}" <<'EOF'
#include "Vibex_prefetch_buffer.h"
#include "verilated.h"

#include <iostream>

static void step_clock(Vibex_prefetch_buffer *top) {
  top->clk_i = 0;
  top->eval();
  top->clk_i = 1;
  top->eval();
  top->clk_i = 0;
  top->eval();
}

int main(int argc, char **argv) {
  Verilated::commandArgs(argc, argv);

  auto *top = new Vibex_prefetch_buffer;

  top->clk_i = 0;
  top->rst_ni = 0;
  top->req_i = 0;
  top->branch_i = 0;
  top->addr_i = 0;
  top->ready_i = 0;
  top->instr_gnt_i = 0;
  top->instr_rvalid_i = 0;
  top->instr_rdata_i = 0;
  top->instr_err_i = 0;
  top->instr_pmp_err_i = 0;
  top->eval();
  step_clock(top);

  top->rst_ni = 1;
  top->branch_i = 1;
  top->addr_i = 0x100;
  top->eval();
  step_clock(top);

  // Issue one request so the prefetch buffer reaches the state where it is
  // holding a pending request and waiting for an incoming rvalid.
  top->branch_i = 0;
  top->req_i = 1;
  top->instr_gnt_i = 1;
  top->eval();

  if (!top->instr_req_o) {
    std::cerr << "SETUP_FAIL: request was not issued in IDLE" << std::endl;
    delete top;
    return 2;
  }

  step_clock(top);

  top->instr_gnt_i = 0;
  top->instr_rvalid_i = 0;
  top->eval();
  const int req_before = top->instr_req_o;

  top->instr_rvalid_i = 1;
  top->eval();
  const int req_after = top->instr_req_o;

  std::cout << "REQ_BEFORE=" << req_before << std::endl;
  std::cout << "REQ_AFTER=" << req_after << std::endl;

  delete top;

  if (req_before != req_after) {
    std::cerr << "COMB_PATH_DETECTED" << std::endl;
    return 1;
  }

  std::cout << "NO_COMB_PATH" << std::endl;
  return 0;
}
EOF

set +e
timeout 900 verilator -sv --cc rtl/ibex_fetch_fifo.sv rtl/ibex_prefetch_buffer.sv \
  --top-module ibex_prefetch_buffer \
  --exe "${TB_CPP}" \
  -Mdir "${OBJ_DIR}" \
  -Wno-fatal \
  --build
build_rc=$?
set -e

echo "HWE_BENCH_RESULTS_START"

if [ "${build_rc}" -ne 0 ]; then
  echo "TEST: ${TEST_NAME} ... FAIL"
  echo "HWE_BENCH_RESULTS_END"
  exit "${build_rc}"
fi

set +e
timeout 60 "${SIM_BIN}"
sim_rc=$?
set -e

if [ "${sim_rc}" -eq 0 ]; then
  echo "TEST: ${TEST_NAME} ... PASS"
  echo "HWE_BENCH_RESULTS_END"
  exit 0
fi

echo "TEST: ${TEST_NAME} ... FAIL"
echo "HWE_BENCH_RESULTS_END"
exit "${sim_rc}"

