#!/bin/bash
set -o pipefail
cd /home/ibex

TEST_NAME="prefetch_addr_stable_until_grant"
TB_DIR="/home/ibex/.tmp/${TEST_NAME}"
SIM_BIN="${TB_DIR}/obj_dir/Vibex_prefetch_buffer"

finish_test() {
  local status="$1"
  local rc="$2"

  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: ${TEST_NAME} ... ${status}"
  echo "HWE_BENCH_RESULTS_END"
  exit "${rc}"
}

rm -rf "${TB_DIR}"
mkdir -p "${TB_DIR}"

cat > "${TB_DIR}/tb_prefetch_addr_stability.cpp" <<'EOF'
#include <cstdint>
#include <iomanip>
#include <iostream>

#include "Vibex_prefetch_buffer.h"
#include "verilated.h"

static vluint64_t main_time = 0;

double sc_time_stamp() { return static_cast<double>(main_time); }

static void eval_only(Vibex_prefetch_buffer *top) {
  top->eval();
}

static void tick(Vibex_prefetch_buffer *top) {
  top->clk_i = 0;
  top->eval();
  ++main_time;
  top->clk_i = 1;
  top->eval();
  ++main_time;
}

int main(int argc, char **argv) {
  Verilated::commandArgs(argc, argv);

  auto *top = new Vibex_prefetch_buffer;

  top->clk_i = 0;
  top->rst_ni = 0;
  top->req_i = 0;
  top->branch_i = 0;
  top->addr_i = 0;
  top->ready_i = 0;
  top->instr_gnt_i = 0;
  top->instr_rdata_i = 0;
  top->instr_err_i = 0;
  top->instr_pmp_err_i = 0;
  top->instr_rvalid_i = 0;

  tick(top);
  tick(top);

  top->rst_ni = 1;
  top->req_i = 1;
  top->branch_i = 1;
  top->addr_i = 0x100;
  eval_only(top);

  uint32_t held_addr = top->instr_addr_o;
  std::cout << "BOOT addr=0x" << std::hex << held_addr << std::dec << std::endl;
  if (!top->instr_req_o || held_addr != 0x100) {
    std::cout << "RESULT: FAIL boot request did not issue at 0x100" << std::endl;
    delete top;
    return 1;
  }

  tick(top);

  top->branch_i = 0;
  top->addr_i = 0x100;
  top->instr_gnt_i = 0;
  eval_only(top);
  if (top->instr_addr_o != held_addr) {
    std::cout << "RESULT: FAIL request address changed before branch stimulus" << std::endl;
    delete top;
    return 1;
  }

  tick(top);

  top->branch_i = 1;
  top->addr_i = 0x200;
  top->instr_gnt_i = 0;
  eval_only(top);

  std::cout << "PENDING old=0x" << std::hex << held_addr
            << " observed=0x" << top->instr_addr_o << std::dec << std::endl;

  if (!top->instr_req_o) {
    std::cout << "RESULT: FAIL request dropped before grant" << std::endl;
    delete top;
    return 1;
  }

  if (top->instr_addr_o != held_addr) {
    std::cout << "RESULT: FAIL request address changed before grant" << std::endl;
    delete top;
    return 1;
  }

  tick(top);

  top->branch_i = 0;
  top->addr_i = 0x200;
  top->instr_gnt_i = 1;
  eval_only(top);
  tick(top);

  std::cout << "RESULT: PASS request address stayed stable until grant" << std::endl;
  delete top;
  return 0;
}
EOF

if ! verilator --cc --exe --build --top-module ibex_prefetch_buffer \
  -Wno-fatal \
  -CFLAGS "-std=c++17" \
  -Mdir "${TB_DIR}/obj_dir" \
  /home/ibex/rtl/ibex_fetch_fifo.sv \
  /home/ibex/rtl/ibex_prefetch_buffer.sv \
  "${TB_DIR}/tb_prefetch_addr_stability.cpp"; then
  finish_test FAIL 1
fi

if "${SIM_BIN}" | tee "${TB_DIR}/sim.log"; then
  finish_test PASS 0
fi

finish_test FAIL 1

