#!/bin/bash
cd /home/ibex
set -uo pipefail

TEST_NAME="icache_ready_valid_without_ready"
TB_DIR="/home/ibex/.tb_${TEST_NAME}"
COMPILE_LOG="${TB_DIR}/compile.log"
SIM_LOG="${TB_DIR}/sim.log"
RESULTS_STARTED=0
RESULTS_ENDED=0

emit_results_start() {
  if [ "${RESULTS_STARTED}" -eq 0 ]; then
    echo "HWE_BENCH_RESULTS_START"
    RESULTS_STARTED=1
  fi
}

emit_results_end() {
  if [ "${RESULTS_STARTED}" -eq 1 ] && [ "${RESULTS_ENDED}" -eq 0 ]; then
    echo "HWE_BENCH_RESULTS_END"
    RESULTS_ENDED=1
  fi
}

finish_test() {
  local result="$1"
  local rc="$2"

  emit_results_start
  echo "TEST: ${TEST_NAME} ... ${result}"
  emit_results_end
  exit "${rc}"
}

rm -rf "${TB_DIR}"
mkdir -p "${TB_DIR}"

cat > "${TB_DIR}/sim_main.cpp" <<'EOF'
#include "Vibex_icache.h"
#include "verilated.h"

vluint64_t main_time = 0;

double sc_time_stamp() {
  return static_cast<double>(main_time);
}

static uint32_t mem_word(uint32_t word_addr) {
  switch (word_addr) {
    case 0x00000000u:
      return 0x00031111u;
    case 0x00000004u:
      return 0xabcd5678u;
    default:
      return 0x00000013u;
  }
}

struct MemPipe {
  bool q1_valid = false;
  bool q2_valid = false;
  uint32_t q1_addr = 0;
  uint32_t q2_addr = 0;
};

static void tick(Vibex_icache *top, MemPipe &mem, int cycle) {
  top->clk_i = 0;
  top->instr_rvalid_i = mem.q2_valid;
  top->instr_rdata_i = mem.q2_valid ? mem_word(mem.q2_addr) : 0;
  top->instr_err_i = 0;
  top->instr_pmp_err_i = 0;
  top->instr_gnt_i = 0;
  top->eval();

  bool req = top->instr_req_o;
  uint32_t req_addr = top->instr_addr_o;
  top->instr_gnt_i = req;
  top->eval();

  req = top->instr_req_o;
  req_addr = top->instr_addr_o;

  top->clk_i = 1;
  top->eval();
  ++main_time;

  if (req || top->instr_rvalid_i || top->valid_o) {
    std::printf("TRACE cycle=%d instr_req=%d instr_addr=%08x instr_rvalid=%d valid=%d ready=%d addr_o=%08x rdata_o=%08x err_o=%d\n",
                cycle,
                req ? 1 : 0,
                req_addr,
                top->instr_rvalid_i ? 1 : 0,
                top->valid_o ? 1 : 0,
                top->ready_i ? 1 : 0,
                top->addr_o,
                top->rdata_o,
                top->err_o ? 1 : 0);
  }

  mem.q2_valid = mem.q1_valid;
  mem.q2_addr = mem.q1_addr;
  mem.q1_valid = req;
  mem.q1_addr = req_addr;
}

int main(int argc, char **argv) {
  Verilated::commandArgs(argc, argv);

  Vibex_icache *top = new Vibex_icache;
  MemPipe mem;

  top->rst_ni = 0;
  top->req_i = 0;
  top->branch_i = 0;
  top->addr_i = 0;
  top->ready_i = 0;
  top->icache_enable_i = 0;
  top->icache_inval_i = 0;

  for (int cycle = 0; cycle < 4; ++cycle) {
    tick(top, mem, cycle);
  }

  top->rst_ni = 1;

  for (int cycle = 4; cycle < 274; ++cycle) {
    tick(top, mem, cycle);
  }

  top->req_i = 1;
  top->branch_i = 1;
  top->addr_i = 0x00000002u;
  tick(top, mem, 274);
  top->branch_i = 0;

  for (int cycle = 275; cycle < 295; ++cycle) {
    tick(top, mem, cycle);

    if (top->valid_o && !top->ready_i) {
      if ((top->addr_o == 0x00000002u) &&
          (top->rdata_o == 0x11110003u) &&
          !top->err_o) {
        std::printf("TB_PASS observed valid_o while ready_i=0\n");
        top->final();
        delete top;
        return 0;
      }

      std::printf("TB_FAIL unexpected response addr=%08x rdata=%08x err=%d\n",
                  top->addr_o, top->rdata_o, top->err_o ? 1 : 0);
      top->final();
      delete top;
      return 1;
    }
  }

  std::printf("TB_FAIL timeout waiting for valid_o with ready_i=0\n");
  top->final();
  delete top;
  return 1;
}
EOF

verilator --cc --exe --build -Wno-fatal -DSYNTHESIS -UVERILATOR \
  --top-module ibex_icache \
  -Mdir "${TB_DIR}/obj_dir" \
  -I/home/ibex/shared/rtl \
  "${TB_DIR}/sim_main.cpp" \
  /home/ibex/rtl/ibex_icache.sv \
  /home/ibex/shared/rtl/prim_generic_ram_1p.sv \
  /home/ibex/shared/rtl/prim_secded_28_22_dec.sv \
  /home/ibex/shared/rtl/prim_secded_28_22_enc.sv \
  /home/ibex/shared/rtl/prim_secded_72_64_dec.sv \
  /home/ibex/shared/rtl/prim_secded_72_64_enc.sv \
  > "${COMPILE_LOG}" 2>&1
compile_rc=$?

cat "${COMPILE_LOG}"
if [ "${compile_rc}" -ne 0 ]; then
  finish_test "FAIL" "${compile_rc}"
fi

"${TB_DIR}/obj_dir/Vibex_icache" 2>&1 | tee "${SIM_LOG}"
sim_rc=${PIPESTATUS[0]}

if [ "${sim_rc}" -eq 0 ] && grep -q "TB_PASS observed valid_o while ready_i=0" "${SIM_LOG}"; then
  finish_test "PASS" 0
fi

finish_test "FAIL" 1

#!/bin/bash
cd /home/ibex

TEST_NAME="prefetch_buffer_early_request"
WORKDIR="/home/ibex/.msb/${TEST_NAME}"

set +e
rm -rf "$WORKDIR"
mkdir -p "$WORKDIR"

cat > "$WORKDIR/sim_main.cpp" <<'EOF'
#include "Vibex_prefetch_buffer.h"
#include "verilated.h"

#include <cstdint>
#include <iostream>
#include <string>

namespace {

struct PendingResp {
  bool valid;
  uint32_t addr;
};

uint32_t MemWord(uint32_t addr) {
  switch (addr) {
    case 0x00000000:
      return 0x00030001;
    case 0x00000004:
      return 0x22231111;
    case 0x00000008:
      return 0x44443333;
    default:
      return 0x00010001;
  }
}

void SetMemoryInputs(Vibex_prefetch_buffer &top, const PendingResp &pending) {
  top.instr_rvalid_i = pending.valid ? 1 : 0;
  top.instr_rdata_i = MemWord(pending.addr);
  top.instr_err_i = 0;
  top.instr_pmp_err_i = 0;
}

void TraceState(const Vibex_prefetch_buffer &top,
                const std::string &step_name,
                int cycle,
                const PendingResp &pending) {
  std::cout << "TRACE cycle=" << cycle
            << " step=" << step_name
            << " req=" << static_cast<int>(top.req_i)
            << " ready=" << static_cast<int>(top.ready_i)
            << " branch=" << static_cast<int>(top.branch_i)
            << " pending_valid=" << static_cast<int>(pending.valid)
            << " pending_addr=0x" << std::hex << pending.addr
            << " valid_o=" << static_cast<int>(top.valid_o)
            << " addr_o=0x" << top.addr_o
            << " instr_req_o=" << static_cast<int>(top.instr_req_o)
            << " instr_addr_o=0x" << top.instr_addr_o
            << " busy_o=" << static_cast<int>(top.busy_o)
            << std::dec << '\n';
}

bool StepCycle(Vibex_prefetch_buffer &top,
               PendingResp &pending,
               bool req,
               bool ready,
               bool branch,
               int &cycle,
               const std::string &step_name,
               const bool check_early_request,
               const bool check_no_bubble) {
  top.req_i = req ? 1 : 0;
  top.ready_i = ready ? 1 : 0;
  top.branch_i = branch ? 1 : 0;
  top.branch_spec_i = branch ? 1 : 0;
  top.addr_i = 0;

  top.clk_i = 0;
  SetMemoryInputs(top, pending);
  top.instr_gnt_i = 0;
  top.eval();

  top.instr_gnt_i = top.instr_req_o;
  top.eval();

  TraceState(top, step_name, cycle, pending);

  if (check_early_request) {
    if (!(top.instr_req_o && top.instr_addr_o == 0x00000008)) {
      std::cerr << "CHECK_FAIL expected immediate refill request for address 0x8"
                << '\n';
      return false;
    }
  }

  if (check_no_bubble) {
    if (!(top.valid_o && top.addr_o == 0x00000006)) {
      std::cerr << "CHECK_FAIL expected next unaligned instruction at address 0x6 without a bubble"
                << '\n';
      return false;
    }
  }

  PendingResp next_pending{top.instr_req_o != 0,
                           static_cast<uint32_t>(top.instr_addr_o)};

  top.clk_i = 1;
  top.eval();

  pending = next_pending;
  ++cycle;
  return true;
}

void TickReset(Vibex_prefetch_buffer &top, PendingResp &pending, int &cycle) {
  top.req_i = 0;
  top.ready_i = 0;
  top.branch_i = 0;
  top.branch_spec_i = 0;
  top.addr_i = 0;
  top.clk_i = 0;
  SetMemoryInputs(top, pending);
  top.instr_gnt_i = 0;
  top.eval();
  top.clk_i = 1;
  top.eval();
  ++cycle;
}

}  // namespace

int main(int argc, char **argv) {
  Verilated::commandArgs(argc, argv);
  Verilated::traceEverOn(false);

  Vibex_prefetch_buffer top;
  PendingResp pending{false, 0};
  int cycle = 0;

  top.rst_ni = 0;
  TickReset(top, pending, cycle);
  TickReset(top, pending, cycle);
  top.rst_ni = 1;

  if (!StepCycle(top, pending, false, false, true, cycle, "branch_init", false, false)) return 1;
  if (!StepCycle(top, pending, true, false, false, cycle, "fetch_word0", false, false)) return 1;
  if (!StepCycle(top, pending, true, false, false, cycle, "fetch_word1", false, false)) return 1;
  if (!StepCycle(top, pending, false, false, false, cycle, "drain_outstanding", false, false)) return 1;
  if (!StepCycle(top, pending, true, false, false, cycle, "check_early_refill", true, false)) return 1;
  if (!StepCycle(top, pending, true, true, false, cycle, "consume_compressed", false, false)) return 1;
  if (!StepCycle(top, pending, true, true, false, cycle, "consume_unaligned32", false, false)) return 1;
  if (!StepCycle(top, pending, true, false, false, cycle, "check_no_fetch_bubble", false, true)) return 1;

  std::cout << "TESTBENCH PASS" << '\n';
  top.final();
  return 0;
}
EOF

timeout 1200s verilator --cc --exe --build --top-module ibex_prefetch_buffer \
  -Wno-fatal -Wno-DECLFILENAME \
  -Mdir "$WORKDIR/obj_dir" \
  -Ivendor/lowrisc_ip/prim/rtl \
  rtl/ibex_fetch_fifo.sv rtl/ibex_prefetch_buffer.sv \
  "$WORKDIR/sim_main.cpp"
build_rc=$?

echo "HWE_BENCH_RESULTS_START"

if [ $build_rc -ne 0 ]; then
  echo "TEST: ${TEST_NAME} ... FAIL"
  echo "HWE_BENCH_RESULTS_END"
  exit $build_rc
fi

timeout 1200s "$WORKDIR/obj_dir/Vibex_prefetch_buffer"
run_rc=$?

if [ $run_rc -eq 0 ]; then
  echo "TEST: ${TEST_NAME} ... PASS"
else
  echo "TEST: ${TEST_NAME} ... FAIL"
fi

echo "HWE_BENCH_RESULTS_END"

exit $run_rc

resolved_issues.body:
from a low-power point-of-view, having the main clock running before fetch_enable_i is set high to kick-start it, is not a great idea ;)

I've traced it up to ibex_controller.sv, where in RESET state, the ctrl_busy is still on default 1'b1. Could we maybe make it 1'b0 in reset state?

To make it work, I also add to activate the internal clock when fetch_enable_i is high, otherwise if fetch_enable_i is only 1 cycle long, you miss it.

