    irq_fast_i               = 15'h0;
    irq_nm_i                 = 1'b0;
    debug_req_i              = 1'b0;
    fetch_enable_i           = 1'b0;
    cycle_count              = 0;
    pre_enable_gated_edges   = 0;
    post_enable_gated_edges  = 0;
    fetch_sent_q             = 1'b0;
    instr_req_seen_q         = 1'b0;
  end

  ibex_core #(
    .PMPEnable                (1'b0),
    .PMPGranularity           (0),
    .PMPNumRegions            (4),
    .MHPMCounterNum           (0),
    .MHPMCounterWidth         (40),
    .RV32E                    (1'b0),
    .RV32M                    (1'b1),
    .RV32B                    (1'b0),
    .BranchTargetALU          (1'b0),
    .WritebackStage           (1'b0),
    .MultiplierImplementation ("fast"),
    .ICache                   (1'b0),
    .ICacheECC                (1'b0),
    .DbgTriggerEn             (1'b0),
    .SecureIbex               (1'b0),
    .DmHaltAddr               (32'h1A110800),
    .DmExceptionAddr          (32'h1A110808)
  ) dut (
    .clk_i          (clk_i),
    .rst_ni         (rst_ni),
    .test_en_i      (test_en_i),
    .hart_id_i      (hart_id_i),
    .boot_addr_i    (boot_addr_i),
    .instr_req_o    (instr_req_o),
    .instr_gnt_i    (instr_gnt_i),
    .instr_rvalid_i (instr_rvalid_i),
    .instr_addr_o   (instr_addr_o),
    .instr_rdata_i  (instr_rdata_i),
