fi

"${SIM_BIN}" --meminit=ram,"${TEST_DIR}/${TEST_NAME}.elf" | tee "${SIM_LOG}"
sim_rc=${PIPESTATUS[0]}

if [ -f "${PROGRAM_LOG}" ]; then
  cat "${PROGRAM_LOG}" | tee -a "${SIM_LOG}"
fi

if [ "${sim_rc}" -eq 0 ] && grep -q "RESULT PASS" "${SIM_LOG}"; then
  finish_test "PASS" 0
fi

finish_test "FAIL" 1

