cat > "${TB_DIR}/tb_internal_irq.sv" <<'EOF'
module tb_internal_irq (
  input logic clk_i
);
  import ibex_pkg::*;

  localparam logic [31:0] BootAddr   = 32'h0000_0200;
  localparam logic [31:0] LoadAddr   = 32'h0000_0020;
  localparam logic [31:0] StatusAddr = 32'h0000_0024;

  logic rst_ni;
  logic instr_req;
  logic instr_gnt;
  logic instr_rvalid;
  logic [31:0] instr_addr;
  logic [38:0] instr_rdata;
  logic instr_err;

  logic data_req;
  logic data_gnt;
  logic data_rvalid;
  logic data_we;
  logic [3:0] data_be;
  logic [31:0] data_addr;
  logic [38:0] data_wdata;
  logic [38:0] data_rdata;
  logic data_err;

  logic dummy_instr_id;
  logic [4:0] rf_raddr_a;
  logic [4:0] rf_raddr_b;
  logic [4:0] rf_waddr_wb;
  logic rf_we_wb;
  logic [31:0] rf_wdata_wb;
  logic [31:0] rf_rdata_a;
  logic [31:0] rf_rdata_b;

  logic [IC_NUM_WAYS-1:0] ic_tag_req;
  logic ic_tag_write;
  logic [IC_INDEX_W-1:0] ic_tag_addr;
  logic [IC_TAG_SIZE-1:0] ic_tag_wdata;
  logic [IC_TAG_SIZE-1:0] ic_tag_rdata [IC_NUM_WAYS];
  logic [IC_NUM_WAYS-1:0] ic_data_req;
  logic ic_data_write;
  logic [IC_INDEX_W-1:0] ic_data_addr;
  logic [IC_LINE_SIZE-1:0] ic_data_wdata;
  logic [IC_LINE_SIZE-1:0] ic_data_rdata [IC_NUM_WAYS];

  logic irq_pending;
  crash_dump_t crash_dump;
  logic double_fault_seen;
  logic alert_minor;
  logic alert_major_internal;
  logic alert_major_bus;
  logic core_busy;

  logic [31:0] imem [0:255];
  logic [31:0] dmem [0:63];
  logic [31:0] rf_mem [0:31];
  logic [31:0] cycle_q;

  logic instr_rsp_valid_q;
  logic [31:0] instr_rsp_addr_q;

  logic data_rsp_valid_q;
  logic [31:0] data_rsp_addr_q;
  logic data_rsp_we_q;
  logic [3:0] data_rsp_be_q;
  logic [38:0] data_rsp_wdata_q;
  logic bad_load_seen_q;

  function automatic logic [31:0] enc_addi(
    input logic [4:0] rd,
    input logic [4:0] rs1,
    input integer imm
  );
    logic signed [11:0] simm;
    begin
      simm = imm[11:0];
      enc_addi = {simm[11:0], rs1, 3'b000, rd, 7'b0010011};
    end
  endfunction

  function automatic logic [31:0] enc_lw(
    input logic [4:0] rd,
    input logic [4:0] rs1,
    input integer imm
  );
    logic signed [11:0] simm;
    begin
      simm = imm[11:0];
      enc_lw = {simm[11:0], rs1, 3'b010, rd, 7'b0000011};
    end
  endfunction

  function automatic logic [31:0] enc_sw(
    input logic [4:0] rs2,
    input logic [4:0] rs1,
    input integer imm
  );
    logic signed [11:0] simm;
    begin
      simm = imm[11:0];
      enc_sw = {simm[11:5], rs2, rs1, 3'b010, simm[4:0], 7'b0100011};
    end
  endfunction

  function automatic logic [31:0] enc_jal(
    input logic [4:0] rd,
    input integer imm
  );
    logic signed [20:0] simm;
    begin
      simm = imm[20:0];
      enc_jal = {simm[20], simm[10:1], simm[11], simm[19:12], rd, 7'b1101111};
    end
  endfunction

  function automatic logic [38:0] good_ecc(input logic [31:0] data_word);
    good_ecc = prim_secded_pkg::prim_secded_inv_39_32_enc(data_word);
  endfunction

  function automatic logic [38:0] bad_ecc(input logic [31:0] data_word);
    bad_ecc = good_ecc(data_word) ^ 39'h40_0000_0000;
  endfunction

  assign rst_ni = (cycle_q >= 32'd5);

  assign instr_gnt = instr_req;
  assign instr_rvalid = instr_rsp_valid_q;
  assign instr_rdata = good_ecc(imem[instr_rsp_addr_q[9:2]]);
  assign instr_err = 1'b0;

  assign data_gnt = data_req;
  assign data_rvalid = data_rsp_valid_q;
  assign data_err = 1'b0;

  always_comb begin
    if (data_rsp_we_q) begin
      data_rdata = good_ecc(32'h0000_0000);
    end else if ((data_rsp_addr_q == LoadAddr) && !bad_load_seen_q) begin
      data_rdata = bad_ecc(dmem[LoadAddr[7:2]]);
    end else begin
      data_rdata = good_ecc(dmem[data_rsp_addr_q[7:2]]);
    end
  end

  always_comb begin
    rf_rdata_a = (rf_raddr_a == 5'd0) ? 32'h0000_0000 : rf_mem[rf_raddr_a];
    rf_rdata_b = (rf_raddr_b == 5'd0) ? 32'h0000_0000 : rf_mem[rf_raddr_b];
  end

  always_ff @(posedge clk_i) begin
    cycle_q <= cycle_q + 32'd1;

    if (!rst_ni) begin
      instr_rsp_valid_q <= 1'b0;
      instr_rsp_addr_q <= 32'h0;
      data_rsp_valid_q <= 1'b0;
      data_rsp_addr_q <= 32'h0;
      data_rsp_we_q <= 1'b0;
      data_rsp_be_q <= 4'h0;
      data_rsp_wdata_q <= '0;
      bad_load_seen_q <= 1'b0;
      for (int i = 0; i < 32; i++) begin
        rf_mem[i] <= 32'h0;
      end
    end else begin
      instr_rsp_valid_q <= instr_req;
      if (instr_req) begin
        instr_rsp_addr_q <= instr_addr;
      end

      data_rsp_valid_q <= data_req;
      if (data_req) begin
        data_rsp_addr_q <= data_addr;
        data_rsp_we_q <= data_we;
        data_rsp_be_q <= data_be;
        data_rsp_wdata_q <= data_wdata;
      end

      if (rf_we_wb && (rf_waddr_wb != 5'd0)) begin
        rf_mem[rf_waddr_wb] <= rf_wdata_wb;
      end

      if (data_rsp_valid_q && !data_rsp_we_q && (data_rsp_addr_q == LoadAddr) && !bad_load_seen_q) begin
        bad_load_seen_q <= 1'b1;
      end

      if (data_rsp_valid_q && data_rsp_we_q) begin
        for (int i = 0; i < 4; i++) begin
          if (data_rsp_be_q[i]) begin
            dmem[data_rsp_addr_q[7:2]][8*i +: 8] <= data_rsp_wdata_q[8*i +: 8];
          end
        end
      end

      if (data_rsp_valid_q && data_rsp_we_q && (data_rsp_addr_q == StatusAddr)) begin
        if (data_rsp_wdata_q[31:0] == 32'd2) begin
          $display("TB_PASS marker=%0d cycle=%0d", data_rsp_wdata_q[31:0], cycle_q);
          $finish;
        end else if (data_rsp_wdata_q[31:0] == 32'd1) begin
          $fatal(1, "TB_FAIL synchronous exception marker=%0d cycle=%0d",
                 data_rsp_wdata_q[31:0], cycle_q);
        end else begin
          $fatal(1, "TB_FAIL unexpected marker=%0d cycle=%0d",
                 data_rsp_wdata_q[31:0], cycle_q);
        end
      end

      if (cycle_q > 32'd300) begin
        $fatal(1, "TB_FAIL timeout cycle=%0d bad_load_seen=%0d", cycle_q, bad_load_seen_q);
      end
    end
  end

  initial begin
    cycle_q = 32'd0;
    instr_rsp_valid_q = 1'b0;
    instr_rsp_addr_q = 32'h0;
    data_rsp_valid_q = 1'b0;
    data_rsp_addr_q = 32'h0;
    data_rsp_we_q = 1'b0;
    data_rsp_be_q = 4'h0;
    data_rsp_wdata_q = '0;
    bad_load_seen_q = 1'b0;

    for (int i = 0; i < 256; i++) begin
      imem[i] = 32'h0000_0013;
    end

    for (int i = 0; i < 64; i++) begin
      dmem[i] = 32'h0000_0000;
    end

    // Exception handler at boot base.
    imem[32'h200 >> 2] = enc_addi(5'd2, 5'd0, 1);
    imem[32'h204 >> 2] = enc_sw(5'd2, 5'd0, StatusAddr);
    imem[32'h208 >> 2] = enc_jal(5'd0, 0);

    // NMI vector jumps to a separate handler body.
    imem[32'h27c >> 2] = enc_jal(5'd0, 32'h300 - 32'h27c);

    // Boot program at boot_addr + 0x80.
    imem[32'h280 >> 2] = enc_lw(5'd1, 5'd0, LoadAddr);
    imem[32'h284 >> 2] = enc_jal(5'd0, -4);

    // NMI handler body.
    imem[32'h300 >> 2] = enc_addi(5'd2, 5'd0, 2);
    imem[32'h304 >> 2] = enc_sw(5'd2, 5'd0, StatusAddr);
    imem[32'h308 >> 2] = enc_jal(5'd0, 0);

    dmem[LoadAddr[7:2]] = 32'hcafe_beef;

    for (int i = 0; i < IC_NUM_WAYS; i++) begin
      ic_tag_rdata[i] = '0;
      ic_data_rdata[i] = '0;
    end
  end

  ibex_core #(
    .SecureIbex       (1'b0),
    .RegFileECC       (1'b0),
    .RegFileDataWidth (32),
    .DummyInstructions(1'b0),
    .ResetAll         (1'b0),
    .MemECC           (1'b1),
    .MemDataWidth     (39),
    .ICache           (1'b0),
    .ICacheECC        (1'b0),
    .PMPEnable        (1'b0),
    .BranchPredictor  (1'b0),
    .WritebackStage   (1'b0)
  ) dut (
    .clk_i               (clk_i),
    .rst_ni              (rst_ni),
    .hart_id_i           (32'h0),
    .boot_addr_i         (BootAddr),
    .instr_req_o         (instr_req),
    .instr_gnt_i         (instr_gnt),
    .instr_rvalid_i      (instr_rvalid),
    .instr_addr_o        (instr_addr),
    .instr_rdata_i       (instr_rdata),
    .instr_err_i         (instr_err),
    .data_req_o          (data_req),
    .data_gnt_i          (data_gnt),
    .data_rvalid_i       (data_rvalid),
    .data_we_o           (data_we),
    .data_be_o           (data_be),
    .data_addr_o         (data_addr),
    .data_wdata_o        (data_wdata),
    .data_rdata_i        (data_rdata),
    .data_err_i          (data_err),
    .dummy_instr_id_o    (dummy_instr_id),
    .rf_raddr_a_o        (rf_raddr_a),
    .rf_raddr_b_o        (rf_raddr_b),
    .rf_waddr_wb_o       (rf_waddr_wb),
    .rf_we_wb_o          (rf_we_wb),
    .rf_wdata_wb_ecc_o   (rf_wdata_wb),
    .rf_rdata_a_ecc_i    (rf_rdata_a),
    .rf_rdata_b_ecc_i    (rf_rdata_b),
    .ic_tag_req_o        (ic_tag_req),
    .ic_tag_write_o      (ic_tag_write),
    .ic_tag_addr_o       (ic_tag_addr),
    .ic_tag_wdata_o      (ic_tag_wdata),
    .ic_tag_rdata_i      (ic_tag_rdata),
    .ic_data_req_o       (ic_data_req),
    .ic_data_write_o     (ic_data_write),
    .ic_data_addr_o      (ic_data_addr),
    .ic_data_wdata_o     (ic_data_wdata),
    .ic_data_rdata_i     (ic_data_rdata),
    .ic_scr_key_valid_i  (1'b0),
    .irq_software_i      (1'b0),
    .irq_timer_i         (1'b0),
    .irq_external_i      (1'b0),
    .irq_fast_i          ('0),
    .irq_nm_i            (1'b0),
    .irq_pending_o       (irq_pending),
    .debug_req_i         (1'b0),
    .crash_dump_o        (crash_dump),
    .double_fault_seen_o (double_fault_seen),
    .fetch_enable_i      (FetchEnableOn),
    .alert_minor_o       (alert_minor),
    .alert_major_internal_o(alert_major_internal),
    .alert_major_bus_o   (alert_major_bus),
    .icache_inval_o      (),
    .core_busy_o         (core_busy)
  );

endmodule
EOF

cat > "${TB_DIR}/sim_main.cpp" <<'EOF'
#include "Vtb_internal_irq.h"
#include "verilated.h"

#include <cstdint>
#include <cstdio>

namespace {

void tick(Vtb_internal_irq* top) {
  top->clk_i = 0;
  top->eval();
  top->clk_i = 1;
  top->eval();
}

}  // namespace

double sc_time_stamp() {
  return 0.0;
}

int main(int argc, char** argv) {
  Verilated::commandArgs(argc, argv);

  auto* top = new Vtb_internal_irq;
  std::uint64_t cycles = 0;

  while (!Verilated::gotFinish() && cycles < 2000) {
    tick(top);
    ++cycles;
  }

  if (!Verilated::gotFinish()) {
    std::fprintf(stderr, "TB_FAIL host timeout cycles=%llu\n",
                 static_cast<unsigned long long>(cycles));
    delete top;
    return 1;
  }

  delete top;
  return 0;
}
