#!/bin/bash
cd /home/ibex

TEST_NAME="core_busy_glitch_clock_gate"

run_test() (
  set -euo pipefail

  export PATH="/tools/verilator/v4.210/bin:/opt/micromamba/envs/ibex/bin:$PATH"

  TB_ROOT=/home/ibex/.tb_core_busy_glitch
  BUILD_ROOT=/home/ibex/build/lowrisc_ibex_core_busy_glitch_0
  SIM_ROOT="${BUILD_ROOT}/sim-verilator"
  SRC_ROOT="${BUILD_ROOT}/src/lowrisc_ibex_core_busy_glitch_0"

  rm -rf "$TB_ROOT" "$BUILD_ROOT"
  mkdir -p "$TB_ROOT"

  cat > "${TB_ROOT}/core_busy_glitch_tb.sv" <<'EOF'
module core_busy_glitch_tb (
  input logic clk_i,
  input logic rst_ni
);
  logic        instr_gnt;
  logic        instr_rvalid;
  logic [31:0] instr_addr;
  logic [31:0] instr_rdata;
  logic [6:0]  instr_rdata_intg;
  logic        instr_err;

  logic        data_req;
  logic        data_gnt;
  logic        data_rvalid;
  logic        data_we;
  logic [3:0]  data_be;
  logic [31:0] data_addr;
  logic [31:0] data_wdata;
  logic [6:0]  data_wdata_intg;
  logic [31:0] data_rdata;
  logic [6:0]  data_rdata_intg;
  logic        data_err;

  logic alert_minor;
  logic alert_major_internal;
  logic alert_major_bus;
  logic core_sleep;

  logic [31:0] unused_instr_data;

  assign instr_rdata = 32'h0000006f;
  assign instr_err = 1'b0;

  assign data_gnt = data_req;
  assign data_rvalid = 1'b0;
  assign data_rdata = 32'h00000000;
  assign data_rdata_intg = 7'h00;
  assign data_err = 1'b0;

  prim_secded_inv_39_32_enc u_instr_rdata_intg (
    .data_i(instr_rdata),
    .data_o({instr_rdata_intg, unused_instr_data})
  );

  logic instr_req_q;
  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      instr_req_q <= 1'b0;
    end else begin
      instr_req_q <= dut.instr_req_o;
    end
  end

  assign instr_gnt = dut.instr_req_o;
  assign instr_rvalid = instr_req_q;

  ibex_top #(
    .SecureIbex(1'b1)
  ) dut (
    .clk_i(clk_i),
    .rst_ni(rst_ni),
    .test_en_i(1'b0),
    .ram_cfg_i('0),
    .hart_id_i(32'h0),
    .boot_addr_i(32'h0),
    .instr_req_o(),
    .instr_gnt_i(instr_gnt),
    .instr_rvalid_i(instr_rvalid),
    .instr_addr_o(instr_addr),
    .instr_rdata_i(instr_rdata),
    .instr_rdata_intg_i(instr_rdata_intg),
    .instr_err_i(instr_err),
    .data_req_o(data_req),
    .data_gnt_i(data_gnt),
    .data_rvalid_i(data_rvalid),
    .data_we_o(data_we),
    .data_be_o(data_be),
    .data_addr_o(data_addr),
    .data_wdata_o(data_wdata),
    .data_wdata_intg_o(data_wdata_intg),
    .data_rdata_i(data_rdata),
    .data_rdata_intg_i(data_rdata_intg),
    .data_err_i(data_err),
    .irq_software_i(1'b0),
    .irq_timer_i(1'b0),
    .irq_external_i(1'b0),
    .irq_fast_i('0),
    .irq_nm_i(1'b0),
    .scramble_key_valid_i(1'b0),
    .scramble_key_i('0),
    .scramble_nonce_i('0),
    .scramble_req_o(),
    .debug_req_i(1'b0),
    .crash_dump_o(),
    .double_fault_seen_o(),
    .fetch_enable_i(4'b0101),
    .alert_minor_o(alert_minor),
    .alert_major_internal_o(alert_major_internal),
    .alert_major_bus_o(alert_major_bus),
    .core_sleep_o(core_sleep),
    .scan_rst_ni(1'b1)
  );
endmodule
EOF

  cat > "${TB_ROOT}/core_busy_glitch.core" <<'EOF'
CAPI=2:
name: "lowrisc:ibex:core_busy_glitch"
description: "Minimal core_busy clock-gating glitch reproducer"

filesets:
  files_tb:
    depend:
      - lowrisc:ibex:ibex_top:0.1
      - lowrisc:prim:secded:0.1
    files:
      - core_busy_glitch_tb.sv: {file_type: systemVerilogSource}

targets:
  sim:
    filesets:
      - files_tb
    toplevel: core_busy_glitch_tb
    default_tool: verilator
    tools:
      verilator:
        mode: cc
        verilator_options:
          - "-Wall"
          - "-Wno-fatal"
EOF

  fusesoc --cores-root=. --cores-root="$TB_ROOT" run --setup --target=sim --tool=verilator \
    lowrisc:ibex:core_busy_glitch

  cd "$SIM_ROOT"
  grep -v -E '(^--exe$|\.c$|\.cc$)' lowrisc_ibex_core_busy_glitch_0.vc > manual.vc

  verilator -f manual.vc -Wno-fatal

  ROOT_H="${SIM_ROOT}/Vcore_busy_glitch_tb___024root.h"
  if grep -q 'core_busy_glitch_tb__DOT__dut__DOT__core_busy_q' "$ROOT_H"; then
    BUSY_FIELD='core_busy_glitch_tb__DOT__dut__DOT__core_busy_q'
    OFF_VALUE='0x0'
  elif grep -q 'core_busy_glitch_tb__DOT__dut__DOT____Vcellout__g_clock_en_secure__DOT__u_prim_core_busy_flop__q_o' "$ROOT_H"; then
    BUSY_FIELD='core_busy_glitch_tb__DOT__dut__DOT____Vcellout__g_clock_en_secure__DOT__u_prim_core_busy_flop__q_o'
    OFF_VALUE='0xA'
  else
